# ===========================================================================
# 1. Parse the implemented tables from opcodeTable.cpp
# ===========================================================================
MODRM_NAMES = {
    "MODRM_NO_MODRM": 0, "MODRM_MOD_MEMORY": 1, "MODRM_MOD_REGISTERS": 2,
    "MODRM_MOD_MEM11": 3, "MODRM_MOD_000": 4, "MODRM_MOD_001": 8,
    "MODRM_MOD_010": 16, "MODRM_MOD_011": 32, "MODRM_MOD_100": 64,
    "MODRM_MOD_101": 128, "MODRM_MOD_110": 256, "MODRM_MOD_111": 512,
    "MODRM_ALL_FILTER": 0xFFFF,
}
MODRM_DIGIT_BIT = {d: (4 << d) for d in range(8)}


# The OpcodeEntry m_mandatoryPrefix values (opcodeTable.h, enum MandatoryPrefix)
MANDATORY_VALUES = {"MANDATORY_NONE": 0x00, "MANDATORY_66": 0x66,
                    "MANDATORY_F2": 0xF2, "MANDATORY_F3": 0xF3}
MPFX_VALUES = {"": 0x00, "66": 0x66, "F2": 0xF2, "F3": 0xF3}


class Entry(object):
    def __init__(self, name, prefix, mask, mandatory, modrm, invalid):
        self.name = name
        self.prefix = prefix
        self.mask = mask
        self.mandatory = mandatory
        self.modrm = modrm
        self.invalid = invalid


def eval_modrm(expr):
    value = 0
    for part in expr.split("|"):
        part = part.strip()
        exact = re.fullmatch(r"MODRM_EXACT\((0x[0-9A-Fa-f]+|\d+)\)", part)
        if part in MODRM_NAMES:
            value |= MODRM_NAMES[part]
        elif exact:
            # Fixed encoding: MODRM_EXACT_FLAG | (byte << 16), see opcodeTable.h
            value |= 0x01000000 | ((int(exact.group(1), 0) & 0xFF) << 16)
        elif part.isdigit():
            value |= int(part)
        elif part:
            raise ValueError("unknown modrm token: %r" % part)
    return value


def parse_tables(cpp_lines):
    """Return {table-name: [Entry, ...]} for the three OpcodeEntry tables."""
    tables = {}
    current = None
    for line in cpp_lines:
        m = re.match(r"^const OpcodeEntry (gIa32\w+)\[\] = \{", line)
        if m:
            current = m.group(1)
            tables[current] = []
            continue
        if current is None:
            continue
        s = line.strip()
        if s.startswith("};"):
            current = None
            continue
        if not s.startswith("{"):
            continue
        m = re.match(r"^\{(.*)\}\s*,?\s*(//.*)?$", s)
        if not m:
            raise ValueError("unparsed table line: %s" % line)
        fields = [f.strip() for f in m.group(1).split(",")]
        if len(fields) != 10:
            raise ValueError("expected 10 fields, got %d: %s" % (len(fields), line))
        name_f = fields[0]
        if name_f == "OPCODEEOT":
            continue
        invalid = name_f == "INVALID"
        prefix = int(fields[1], 16)
        mask = int(fields[2], 16)
        mandatory = MANDATORY_VALUES[fields[3]]
        modrm = eval_modrm(fields[7])
        tables[current].append(Entry(name_f.strip('"'), prefix, mask, mandatory, modrm, invalid))
    return tables


# ===========================================================================
# 2. Parse nasm insns.dat and expand the '#' / '$' size templates
# ===========================================================================
SIZE_DIGITS = {"b": "8", "w": "16", "d": "32", "q": "64"}
AX_NAMES = {"b": "al", "w": "ax", "d": "eax", "q": "rax"}
CX_NAMES = {"b": "cl", "w": "cx", "d": "ecx", "q": "rcx"}


def subst_op(tok, letter):
    if "#" not in tok or letter not in SIZE_DIGITS:
        return tok
    if tok == "ax#":
        return AX_NAMES[letter]
    if tok == "cx#":
        return CX_NAMES[letter]
    return tok.replace("##", SIZE_DIGITS[letter]).replace("#", SIZE_DIGITS[letter])


def subst_enc(tok, letter):
    if "#" not in tok or letter not in SIZE_DIGITS:
        return tok
    m = re.fullmatch(r"([0-9a-fA-F]{2})\+r#", tok)
    if m:
        base = int(m.group(1), 16) + (0 if letter == "b" else 8)
        return "%02x+r" % base
    m = re.fullmatch(r"([0-9a-fA-F]{2})#", tok)
    if m:
        base = int(m.group(1), 16) + (0 if letter == "b" else 1)
        return "%02x" % base
    if tok.startswith("o#"):
        return {"b": "", "w": "o16", "d": "o32", "q": "o64"}[letter]
    if tok.startswith("optw#") or tok.startswith("a#"):
        return ""
    return tok.replace("##", SIZE_DIGITS[letter]).replace("#", SIZE_DIGITS[letter])


def parse_flags(text):
    conds = re.findall(r"\((\w+):([\w\-/]+)\)", text)
    rest = re.sub(r"\(\w+:[\w\-/]+\)", " ", text)
    flags = set(t for t in re.split(r"[,\s]+", rest) if t)
    return flags, conds


CC_TABLE = [
    (0x0, ["O"]), (0x1, ["NO"]), (0x2, ["B", "C", "NAE"]), (0x3, ["AE", "NB", "NC"]),
    (0x4, ["E", "Z"]), (0x5, ["NE", "NZ"]), (0x6, ["BE", "NA"]), (0x7, ["A", "NBE"]),
    (0x8, ["S"]), (0x9, ["NS"]), (0xA, ["P", "PE"]), (0xB, ["NP", "PO"]),
    (0xC, ["L", "NGE"]), (0xD, ["NL", "GE"]), (0xE, ["LE", "NG"]), (0xF, ["NLE", "G"]),
]
ALU_OPS = [("ADD", 0), ("OR", 1), ("ADC", 2), ("SBB", 3), ("AND", 4), ("SUB", 5),
           ("XOR", 6), ("CMP", 7)]
SHIFT_OPS = [("ROL", 0, ["ROL"]), ("ROR", 1, ["ROR"]), ("RCL", 2, ["RCL"]),
             ("RCR", 3, ["RCR"]), ("SHL", 4, ["SHL", "SAL"]), ("SHR", 5, ["SHR"]),
             ("SAR", 7, ["SAR"])]


def macro_lines():
    """Synthesize the lines NASM generates from its $arith/$shift/Jcc/CMOVcc/SETcc macros."""
    out = []
    for name, d in ALU_OPS:
        b = d * 8
        out.append("$bwdq %s rm#,reg#  [mr: o# %02x# /r]  8086" % (name, b))
        out.append("$bwdq %s reg#,rm#  [rm: o# %02x# /r]  8086" % (name, b + 2))
        out.append("$bwdq %s ax#,imm#  [-i: o# %02x# i#]  8086" % (name, b + 4))
        out.append("$bwdq %s rm#,imm#  [mi: o# 80# /%d i#]  8086" % (name, d))
        out.append("$wd %s rm#,sbyte#  [mi: o# 83 /%d ib]  8086" % (name, d))
    for name, digit, aliases in SHIFT_OPS:
        for a in aliases:
            out.append("$bwdq %s rm#,imm8  [mi: o# c0# /%d ib]  8086" % (a, digit))
            out.append("$bwdq %s rm#,1  [m1: o# d0# /%d]  8086" % (a, digit))
            out.append("$bwdq %s rm#,reg_cl  [mc: o# d2# /%d]  8086" % (a, digit))
    for cc, aliases in CC_TABLE:
        for a in aliases:
            out.append("J%s short  [i: os %02x rel8]  8086" % (a, 0x70 + cc))
            out.append("J%s near  [i: os 0f %02x rel]  386" % (a, 0x80 + cc))
            out.append("$wdq CMOV%s reg#,rm#  [rm: o# 0f %02x /r]  P6" % (a, 0x40 + cc))
            out.append("SET%s rm8  [m: 0f %02x /0]  386" % (a, 0x90 + cc))
    return out


MACRO_MNEM = re.compile(r"\b(Jcc|CMOVcc|SETcc|CFCMOVcc|CMPcc\w*|SETcc\w*)\b")


def load_insns(path):
    """Return a list of expanded variants (dicts)."""
    variants = []
    stats = defaultdict(int)
    with open(path, encoding="utf-8", errors="replace") as fh:
        raw_lines = fh.readlines()
    raw_lines = [(n, r) for n, r in enumerate(raw_lines, 1)] + [(0, r + "\n") for r in macro_lines()]
    for lineno, raw in raw_lines:
        if True:
            line = raw.split(";", 1)[0].rstrip("\n")
            if not line.strip():
                continue
            if MACRO_MNEM.search(line) and lineno:
                stats["macro-template-skipped"] += 1
                continue
            line = line.strip()
            tm = re.match(r"^((?:\$\S+\s+)*)", line)
            templates = tm.group(1).split() if tm else []
            line = line[len(tm.group(1)):] if tm else line
            m = re.match(r"^(\S+)\s+(\S+)\s+\[([^\]]*)\]\s*(.*)$", line)
            if not m:
                stats["no-encoding"] += 1
                continue
            mnem, ops_text, enc_text, flag_text = m.groups()
            letters = ""
            for tok in templates:
                if re.fullmatch(r"\$[bwdqz]+", tok):
                    for ch in tok[1:]:
                        for add in ("wd" if ch == "z" else ch):
                            if add in "bwdq" and add not in letters:
                                letters += add
            letters = "".join(ch for ch in "bwdq" if ch in letters)
            template = "$" + letters if letters else None
            base_flags, conds = parse_flags(flag_text)
            if not letters and ("#" in ops_text or "#" in enc_text or "#" in mnem):
                stats["size-template-without-size-letter"] += 1
                letters = "wdq"
            if not letters:
                letters = "-"
            ops = [] if ops_text == "void" else ops_text.split(",")
            enc_toks = enc_text.split()
            for letter in letters:
                if letter == "q":
                    stats["dropped-q-size"] += 1
                    continue
                flags = set(base_flags)
                for group, flag in conds:
                    if letter != "-" and letter in group:
                        flags.add(flag)
                v_ops = [subst_op(o, letter) if letter != "-" else o for o in ops]
                v_enc = [subst_enc(t, letter) if letter != "-" else t for t in enc_toks]
                v_mnem = mnem.rstrip("%")
                if "#" in v_mnem:
                    v_mnem = v_mnem.replace("CX#", "ECX") if letter == "d" else v_mnem.replace("#", "")
                variants.append({
                    "line": lineno, "mnem": v_mnem.lower(), "ops": v_ops,
                    "flags": flags, "enc": v_enc, "letter": letter,
                })
    return variants, stats


# ===========================================================================
# 3. Decode an encoding into a Form
# ===========================================================================
def is_hex_tok(t):
    return re.fullmatch(r"[0-9a-fA-F]{2}(\+r[bwdoq]?|\+i)?", t) is not None


def hex_val(t):
    m = re.fullmatch(r"([0-9a-fA-F]{2})(\+r[bwdoq]?|\+i)?", t)
    return int(m.group(1), 16), bool(m.group(2))


VEX_MAP_NAMES = {"0f": "0F", "0f38": "0F38", "0f3a": "0F3A", "m1": "0F",
                 "m2": "0F38", "m3": "0F3A", "map5": "MAP5", "map6": "MAP6"}
IGNORE_TOK = re.compile(
    r"^(o16|o32|o64|o64nw|osz|o#|a16|a32|optw.*|norex.*|rex\.[lw]|hle.*|hlexr|hlenl|"
    r"hlexs|lock|lock1|wait|nof3|nw|mustrep|nobnd|bnd|ds|np|nf3|f3i?|f2i?|66i?|"
    r"rex|ib.*|iw.*|id.*|iq.*|iwd.*|i#|imm.*|rel.*|sbyte.*|vsib[xyz]|vsibz|"
    r"norexw|norexb|norexr|norexx|nf\d*|nd\d*|evex\.dfv.*|/is4|lig|nof2|cx|cl)$")


def parse_enc(toks, flags):
    """Return a dict describing the opcode part of an encoding."""
    f = {"map": None, "kind": None, "mpfx": "", "op": None, "plusr": False,
         "tail": ("none",), "vexL": None, "vexW": None, "vexpp": None}
    # Drop form codes such as "mr:", "rvm:fv:"; a code can be glued to the next token ("rm:hvm:evex...").
    toks = [t.split(":")[-1] for t in toks]
    toks = [t for t in toks if t]
    n = len(toks)
    # VEX / EVEX / XOP family
    for idx, t in enumerate(toks):
        if re.match(r"^(vex|evex|xop)[+.]", t) or t in ("vex", "evex", "xop"):
            comps = [c for c in t.replace("+", "").split(".")[1:]]
            f["kind"] = t.split(".")[0].replace("+", "").upper()
            f["map"] = "0F"
            for c in comps:
                if c in VEX_MAP_NAMES:
                    f["map"] = VEX_MAP_NAMES[c]
                elif c in ("66", "f2", "f3"):
                    f["vexpp"] = c.upper()
                elif c in ("128", "256", "512", "l0", "l1", "lz", "lig"):
                    f["vexL"] = c
                elif c in ("w0", "w1", "wig"):
                    f["vexW"] = c.upper()
            i = idx + 1
            while i < n and not is_hex_tok(toks[i]):
                i += 1
            if i >= n:
                return None
            val, plus = hex_val(toks[i])
            f["op"] = val
            f["plusr"] = plus
            rest = toks[i + 1:]
            if any(t2 in ("/r", "/is4") for t2 in rest):
                f["tail"] = ("r",)
            elif rest and re.fullmatch(r"/[0-7]", rest[0]):
                f["tail"] = ("d", int(rest[0][1]))
            else:
                f["tail"] = ("none",)
            return f
    # Legacy: prefixes, escape, opcode
    i = 0
    esc = None
    while i < n:
        t = toks[i]
        # Prefix tokens only count before the escape/opcode; after 0F a
        # 66/F2/F3 token is the opcode byte itself (e.g. 0F 66 PCMPGTD).
        if esc is None and t in ("66", "66i"):
            f["mpfx"] = "66"
        elif esc is None and t in ("f2", "f2i"):
            f["mpfx"] = "F2"
        elif esc is None and t in ("f3", "f3i"):
            f["mpfx"] = "F3"
        elif t == "0f" and esc is None:
            esc = "0F"
            if i + 1 < n and toks[i + 1] in ("38", "3a") and i + 2 < n:
                esc = "0F38" if toks[i + 1] == "38" else "0F3A"
                i += 1
        elif t in ("0f38", "0f3a") and esc is None and i + 1 < n:
            esc = t.upper()
        elif is_hex_tok(t) or t.startswith("/"):
            break
        elif IGNORE_TOK.match(t):
            pass
        else:
            pass
        i += 1
    if i >= n or not is_hex_tok(toks[i]):
        return None  # no opcode byte (e.g. pure prefix line, or 0F 3A with no third byte)
    val, plus = hex_val(toks[i])
    j = i + 1
    if esc is None:
        if 0xD8 <= val <= 0xDF and j < n and (is_hex_tok(toks[j]) or toks[j].startswith("/")):
            f["map"] = "X87"
            f["op"] = val
            if toks[j].startswith("/"):
                f["tail"] = ("d", int(toks[j][1]))
            else:
                sval, splus = hex_val(toks[j])
                f["tail"] = ("i", (sval >> 3) & 7) if splus else ("lit", sval)
                if splus:
                    f["plusr"] = True
            return f
        f["map"] = "1"
    else:
        f["map"] = esc
    f["op"] = val
    f["plusr"] = plus
    if plus:
        f["tail"] = ("none",)
        return f
    if j < n and toks[j].startswith("/"):
        f["tail"] = ("r",) if toks[j] in ("/r", "/is4") else ("d", int(toks[j][1]))
    elif j < n and is_hex_tok(toks[j]):
        f["tail"] = ("lit", hex_val(toks[j])[0])
    else:
        f["tail"] = ("none",)
    return f


def sdm_enc_text(f):
    """SDM-style encoding text, e.g. '66 0F D4 /r', 'D9 C0+i' or 'VEX.128.66.0F38.W0 F7 /r'."""
    t = f["tail"]
    if t[0] == "r":
        tail = "/r"
    elif t[0] == "d":
        tail = "/%d" % t[1]
    elif t[0] == "i":
        tail = "%02X+i" % (0xC0 | (t[1] << 3))
    elif t[0] == "lit":
        tail = "%02X" % t[1]
    else:
        tail = ""
    if f["kind"]:
        comps = [f["kind"]]
        if f["vexL"]:
            comps.append(f["vexL"].upper())
        if f["vexpp"]:
            comps.append(f["vexpp"])
        comps.append(f["map"])
        if f["vexW"]:
            comps.append(f["vexW"])
        pieces = [".".join(comps), "%02X%s" % (f["op"], "+r" if f["plusr"] else "")]
    elif f["map"] == "X87":
        pieces = ["%02X" % f["op"]]
    else:
        pieces = [f["mpfx"]] if f["mpfx"] else []
        if f["map"] in ("0F", "0F38", "0F3A"):
            pieces.append("0F")
            if f["map"] != "0F":
                pieces.append(f["map"][2:])
        pieces.append("%02X%s" % (f["op"], "+r" if f["plusr"] else ""))
    pieces.append(tail)
    return " ".join(p for p in pieces if p)


def form_code(enc_toks):
    """NASM operand-field code, e.g. 'rm:' -> ['r', 'm'] (one letter per operand).

    m = ModRM r/m field, r = ModRM reg field (or the +r opcode bits),
    i = immediate, - = implicit operand.  None when the line has no code.
    """
    for tok in enc_toks:
        if ":" in tok:
            return list(tok.split(":")[0])
    return None


def make_form(v):
    p = parse_enc(v["enc"], v["flags"])
    if p is None:
        return None
    form = dict(p)
    flags = set(v["flags"])
    if any(t in ("o64", "o64nw", "rex.w") for t in v["enc"]):
        flags.add("REXW")   # REX.W operand size: 64-bit only, never in 32/16-bit mode
    form.update({"mnem": v["mnem"], "ops": [o for o in v["ops"] if o != "void"],
                 "flags": flags, "line": v["line"], "letter": v["letter"],
                 "fields": form_code(v["enc"])})
    form["sdm"] = sdm_enc_text(form)
    return form


# ===========================================================================
# 4. Filtering, classification and feature tagging
# ===========================================================================
def drop_reason(form):
    flags = form["flags"]
    if flags & (ALWAYS_DROP_FLAGS - {"LONG", "X86_64"}):
        return "64-bit-only/APX/pseudo (%s)" % ",".join(sorted(flags & ALWAYS_DROP_FLAGS))
    if flags & {"LONG", "X86_64"}:
        # NASM marks some forms LONG/X86_64 that the SDM lists as valid in
        # compatibility mode (RDTSCP, RDPKRU, LFENCE): keep those.
        row = sdm_row_for(form)
        if row is None or not row["compat"]:
            return "64-bit-only (%s)" % ",".join(sorted(flags & {"LONG", "X86_64"}))
    if any(fl.startswith("AMX") for fl in flags):
        return "AMX (64-bit-only)"
    if form["kind"] == "XOP":
        return "XOP (AMD-only)"
    if flags & SDM_AUTHORITY_FLAGS and sdm_row_for(form) is None:
        return "AMD/obsolete/undocumented, not in SDM 093 (%s)" % ",".join(sorted(flags & SDM_AUTHORITY_FLAGS))
    return None


def feature_tag(mnem, flags):
    if mnem in TAG_BY_MNEM:
        return TAG_BY_MNEM[mnem]
    for flag, tag in FLAG_TAG_ORDER:
        if flag in flags:
            return tag
    # NASM conditional flags such as AVX512(b:DQ/w:F/BW) are AVX-512 forms.
    if any(fl.startswith("AVX512(") for fl in flags):
        return "avx512f"
    for fl in sorted(flags):
        if fl not in NON_FEATURE_FLAGS and not fl.startswith("AVX") and "(" not in fl:
            return fl.lower()
    return "base"


def covers_byte(entry, value):
    return (value & entry.mask) == (entry.prefix & entry.mask)


# NASM spells some instructions with an alias that the table names differently.
ALIAS_OF = {
    "sal": "shl", "loopz": "loope", "loopnz": "loopne", "retn": "ret",
    "int3": "int", "int03": "int", "brkpt": "int", "int1": "icebp", "int01": "icebp",
    "ins": "insb", "outs": "outsb", "movs": "movsb", "cmps": "cmpsb",
    "lods": "lodsb", "stos": "stosb", "scas": "scasb", "salc": "salc",
}

def canon(name):
    """Canonical mnemonic: condition-code aliases (jc/jb, cmovnae/cmovb) and ALIAS_OF."""
    name = ALIAS_OF.get(name, name)
    m = re.fullmatch(r"(j|cmov|set)([a-z]+)", name)
    if m:
        for cc, aliases in CC_TABLE:
            if m.group(2) in [a.lower() for a in aliases]:
                return "%s#%x" % (m.group(1), cc)
    return name


def name_ok(table_name, mnem):
    """Does a dismount table name cover NASM mnemonic 'mnem'?

    Table names use '#' for the string/size suffix (movs##, pusha#d, j#ecxz),
    '/' for the 16/32-bit pair (cbw/cwde), and the usual condition-code aliases.
    """
    for t in table_name.lower().split("/"):
        if "#" in t:
            pat = "^" + re.escape(t).replace("\\#", "[a-z]*") + "$"
            pat = pat.replace("d$", "d?$")
            if re.match(pat, mnem) or (t == "j#ecxz" and mnem == "jcxz"):
                return True
            continue
        if t == mnem or canon(t) == canon(mnem):
            return True
    return False


def implemented(form, tables):
    """True when dismount's tables already decode this form."""
    if form["kind"] or form["map"] in ("0F38", "0F3A"):
        return False
    tail = form["tail"]
    op = form["op"]
    # The entries must carry the same mandatory prefix (66/F2/F3, or none)
    want_mandatory = MPFX_VALUES[form["mpfx"]]
    if form["map"] == "1":
        ents = [e for e in tables["gIa32OneByteOpcodeTable"] if not e.invalid and covers_byte(e, op)
                and name_ok(e.name, form["mnem"]) and e.mandatory == want_mandatory]
        if not ents:
            return False
        if tail[0] == "none":
            return any(e.modrm == 0 for e in ents)
        if tail[0] == "r":
            return any(e.modrm != 0 for e in ents)
        if tail[0] == "d":
            return any(e.modrm & MODRM_DIGIT_BIT[tail[1]] or e.modrm == 0xFFFF for e in ents)
        return True  # fixed trailing byte in the one-byte map (e.g. AAM): accept
    if form["map"] == "0F":
        ents = [e for e in tables["gIa32TwoBytesOpcodeTable"] if not e.invalid and covers_byte(e, op)
                and name_ok(e.name, form["mnem"]) and e.mandatory == want_mandatory]
        if not ents:
            return False
        if tail[0] == "none":
            return any(e.modrm == 0 for e in ents)
        if tail[0] == "r":
            return any(e.modrm != 0 for e in ents)
        if tail[0] == "d":
            return any(e.modrm & MODRM_DIGIT_BIT[tail[1]] or e.modrm == 0xFFFF for e in ents)
        return False  # literal ModRM (e.g. 0F 01 C1): table cannot match an exact byte
    if form["map"] == "X87":
        ents = [e for e in tables["gIa32FPUOpcodeTable"] if not e.invalid and e.prefix == op]
        if tail[0] == "d":
            return any(e.modrm & MODRM_DIGIT_BIT[tail[1]] or e.modrm == 0xFFFF for e in ents)
        # register (+i) and literal forms: match by mnemonic name and digit
        if tail[0] == "i":
            digit = tail[1]
        elif tail[0] == "lit":
            digit = (tail[1] >> 3) & 7
        else:
            digit = None
        want = X87_ALIASES.get(form["mnem"], form["mnem"])
        for e in ents:
            if _x87_norm(e.name) != _x87_norm(want):
                continue
            if e.modrm == 0 or (digit is not None and (e.modrm & MODRM_DIGIT_BIT[digit])):
                return True
        return False
    return False


def _x87_norm(name):
    name = name.lower()
    if name.startswith("fn"):
        name = "f" + name[2:]
    return name


FIXED_OPND = {"al": "OPND_AL", "reg_al": "OPND_AL", "cl": "OPND_CL", "reg_cl": "OPND_CL",
              "dx": "OPND_DX", "reg_dx": "OPND_DX", "ax": "OPND_eAX", "eax": "OPND_eAX",
              "reg_ax": "OPND_eAX", "reg_eax": "OPND_eAX", "reg_bx": "OPND_eBX",
              "reg_ebx": "OPND_eBX", "reg_bp": "OPND_eBP", "reg_ebp": "OPND_eBP",
              "reg_si": "OPND_eSI", "reg_esi": "OPND_eSI", "reg_di": "OPND_eDI",
              "reg_edi": "OPND_eDI", "reg_cs": "OPND_CS", "reg_ds": "OPND_DS",
              "reg_es": "OPND_ES", "reg_ss": "OPND_SS", "reg_fs": "OPND_FS", "reg_gs": "OPND_GS",
              "1": "OPND_ONE", "3": "OPND_THREE"}
REG_FIELD = {"reg8": "OPND_GP_8BIT_MODRM", "reg16": "OPND_GP_16_32BIT",
             "reg32": "OPND_GP_16_32BIT", "reg": "OPND_GP_16_32BIT",
             "reg_sreg": "OPND_GP_SEGMENT_MODRM", "reg_creg": "OPND_CTRL_MODRM",
             "reg_dreg": "OPND_DBG_MODRM", "xmmreg": "OPND_SIMD_MODRM",
             "mmxreg": "OPND_MMX_MODRM"}
# The r/m operands of the MMX and SSE registers (register or memory)
SIMD_RM_MAP = {"xmmrm": "OPND_SIMD_RM", "xmmrm128": "OPND_SIMD_RM",
               "xmmrm64": "OPND_SIMD_RM_QWORD", "mmxrm": "OPND_MMX_RM",
               "mmxrm64": "OPND_MMX_RM"}
RM_FIELD = {"8": "OPND_MODRM_BYTEPTR", "16": "OPND_MODRM_WORDPTR", "32": "OPND_MODRM_dWORDPTR",
            "64": "OPND_MODRM_dWORDPTR", "128": "OPND_MODRM_dWORDPTR", "256": "OPND_MODRM_dWORDPTR"}


def rm_type(base):
    """ModRM r/m operand type for an rm/mem/xmmrm operand name."""
    digits = re.search(r"(\d+)$", base)
    if base.startswith(("rm8", "mem8", "reg8")) or base == "rm8":
        return "OPND_MODRM_BYTEPTR"
    if digits and digits.group(1) in RM_FIELD:
        return RM_FIELD[digits.group(1)]
    if base.startswith(("reg16", "rm16", "mem16")):
        return "OPND_MODRM_WORDPTR"
    return "OPND_MODRM_dWORDPTR"


def operand_types(form):
    """Return (list of OperandType names, reason-if-missing)."""
    ops = form["ops"]
    fields = form.get("fields") or []
    if len(ops) > 3:
        return None, "more than three operands"
    result = []
    missing = []
    for k, tok in enumerate(ops):
        base = tok.split("|")[0].rstrip("*?")
        if base.startswith("sbyte"):
            base = "sbyte8"
        fld = fields[k] if k < len(fields) else None
        if base in FIXED_OPND:
            result.append(FIXED_OPND[base])
        elif base in ("imm8", "sbyte8", "ib"):
            result.append("OPND_IMMEDIATE_8BIT")
        elif base == "imm16":
            result.append("OPND_IMMEDIATE_16BIT")
        elif base in ("imm", "imm32"):
            result.append("OPND_IMMEDIATE_DS")
        elif base == "rel8":
            result.append("OPND_IMMEDIATE_OFFSET_SHORT_8")
        elif base == "rel32":
            result.append("OPND_IMMEDIATE_OFFSET_LONG_32")
        elif base in ("rel", "near"):
            result.append("OPND_IMMEDIATE_OFFSET_DS")
        elif base == "mem_offs":
            result.append("OPND_MEMREF_OFFSET_DS")
        elif base in ("reg_sreg", "reg_creg", "reg_dreg") or (base in REG_FIELD and fld != "m"):
            if form["plusr"] and fld == "r" and base in ("reg8", "reg16", "reg32", "reg"):
                result.append("OPND_ONEBYTES_OPCODE_GP_8" if base == "reg8" else "OPND_ONEBYTES_OPCODE_GP_16_32")
            elif base in REG_FIELD:
                result.append(REG_FIELD[base])
            else:
                missing.append("operand %s" % tok)
        elif base in SIMD_RM_MAP:
            result.append(SIMD_RM_MAP[base])
        elif base in ("reg8", "reg16", "reg32", "reg") or base.startswith(("rm", "mem", "xmmrm")) or fld == "m":
            if base in OPND_MISSING:
                missing.append(OPND_MISSING[base])
            else:
                result.append(rm_type(base))
        elif base in OPND_MISSING:
            missing.append(OPND_MISSING[base])
        else:
            missing.append("operand %s" % tok)
    if missing:
        return None, "; ".join(sorted(set(missing)))
    while len(result) < 3:
        result.append("OPND_NO_OPERAND")
    return result, None


def modrm_expr(tail):
    if tail[0] == "none":
        return "MODRM_NO_MODRM"
    if tail[0] == "r":
        return "MODRM_ALL_FILTER"
    if tail[0] == "d":
        return "MODRM_MOD_MEM11 | MODRM_MOD_%s" % format(tail[1], "03b")
    return None


def render_ops(form):
    out = []
    for tok in form["ops"]:
        base = tok.split("|")[0].rstrip("*?")
        if base.startswith("sbyte"):
            base = "sbyte8"
        out.append(RENDER.get(base, base))
    return ", ".join(out)


def make_entry_text(form):
    """Return the ready-to-uncomment table entry, or (None, reason)."""
    if form["kind"] or form["map"] not in ("1", "0F", "X87"):
        return None, "needs 3-byte/VEX/EVEX support"
    if form["tail"][0] == "lit":
        return None, "needs exact fixed ModRM/immediate byte match %02X" % form["tail"][1]
    if form["tail"][0] == "i":
        return None, "needs operand type: ST(i) register operand (+i encoding)"
    if BRANCH_LIKE.match(form["mnem"]):
        return None, "needs review: branch/flow property (Opcode::FLOW_*)"
    ops, why = operand_types(form)
    if ops is None:
        return None, "needs operand type: %s" % why
    mnem = form["mnem"]
    if form["map"] == "X87":
        prefix, mask = form["op"], 0xFF
    else:
        prefix, mask = form["op"], (0xF8 if form["plusr"] else 0xFF)
    modrm = modrm_expr(form["tail"])
    if form["map"] == "X87" and form["tail"][0] == "d":
        modrm = "MODRM_MOD_MEM11 | MODRM_MOD_%s" % format(form["tail"][1], "03b")
    mandatory = {0x00: "MANDATORY_NONE", 0x66: "MANDATORY_66",
                 0xF2: "MANDATORY_F2", 0xF3: "MANDATORY_F3"}[MPFX_VALUES[form["mpfx"]]]
    text = '{"%s", 0x%02X, 0x%02X, %s, %s, %s, %s, %s, true, Opcode::FLOW_NO_ALTER},' % (
        mnem, prefix, mask, mandatory, ops[0], ops[1], ops[2], modrm)
    return text, None


# ===========================================================================
# 5. SDM Vol. 2 authority list and cross-check
# ===========================================================================
# Operand/encoding codes printed where the mnemonic is not on the same line; a
# row whose "mnemonic" is one of these matches on opcode, prefix and tail only.
OPEN_CODES = {"ZO", "MR", "RM", "M", "A", "I", "MI", "RMI", "RVM", "MRI", "FD", "TD", "OI",
              "NP", "RVMI", "MRC", "RMV", "VMI", "MVR", "M1", "MC", "RVMR", "RVMS", "O", "D", "S"}
VALIDITY_TOKENS = {"Valid", "N.E.", "N.P.", "V/V", "V/N.E.", "N.E./V", "N.E./N.E.", "N.P./V"}
PREFIX_BYTES = {0xF0, 0xF2, 0xF3, 0x66, 0x67, 0x2E, 0x36, 0x3E, 0x26, 0x64, 0x65, 0x9B}


def parse_vol2(path):
    """Yield (map, mpfx, op, tail, plusr, lineno, text) for legacy opcode lines."""
    rows = []
    with open(path, encoding="utf-8", errors="replace") as fh:
        for lineno, line in enumerate(fh, 1):
            toks = line.split()
            if len(toks) < 2:
                continue
            if any(t.startswith(("REX", "VEX", "EVEX", "XOP", "MVEX", "W0", "W1")) for t in toks[:3]):
                continue
            i = 0
            mpfx = ""
            if toks[0] in ("NP", "66", "F2", "F3"):
                mpfx = "" if toks[0] == "NP" else toks[0]
                i = 1
            if i < len(toks) and toks[i] == "9B":
                i += 1
            esc = "1"
            if i < len(toks) and toks[i] == "0F":
                esc = "0F"
                i += 1
                if i < len(toks) and toks[i] in ("38", "3A"):
                    esc = "0F" + toks[i]
                    i += 1
            if i >= len(toks) or not re.fullmatch(r"[0-9A-F]{2}(\+r[bwdoq]?|\+i)?", toks[i]):
                continue
            prim = toks[i]
            i += 1
            if mpfx == "" and esc == "1" and int(prim[:2], 16) in PREFIX_BYTES:
                continue
            if any(t2 in ("REP", "REPE", "REPNE", "REPZ", "REPNZ", "LOCK") for t2 in toks[i:i + 3]):
                mpfx = ""
            extra = []
            while i < len(toks) and re.fullmatch(r"[0-9A-F]{2}(\+i)?", toks[i]) and toks[i] not in ("CD", "CB", "CW", "CP", "CO"):
                extra.append(toks[i])
                i += 1
            pv = int(prim[:2], 16)
            plusr = "+r" in prim
            if esc == "1" and 0xD8 <= pv <= 0xDF and (extra or (i < len(toks) and toks[i].startswith("/"))):
                mapn = "X87"
            else:
                mapn = esc
            if mapn == "X87":
                if extra:
                    e0 = extra[0]
                    if e0.endswith("+i"):
                        tail = ("i", (int(e0[:2], 16) >> 3) & 7)
                    else:
                        tail = ("lit", int(e0[:2], 16))
                elif i < len(toks) and re.fullmatch(r"/[0-7]", toks[i]):
                    tail = ("d", int(toks[i][1]))
                else:
                    continue
                mnem = next((t2 for t2 in toks[i:i + 6] if re.fullmatch(r"[A-Z][A-Z0-9]+-?", t2)), "")
                mnem = "" if mnem.rstrip("-") in OPEN_CODES else mnem.rstrip("-").lower()
                vals = [t2 for t2 in toks[i:] if t2 in VALIDITY_TOKENS][:2]
                rows.append({"map": mapn, "mpfx": mpfx, "op": pv, "tail": tail, "plusr": False,
                             "line": lineno, "text": line.strip(), "mnem": mnem,
                             "compat": (len(vals) == 2 and vals[1] in ("Valid", "V")) or vals == ["V/V"]})
                continue
            if mapn == "1" and pv in (0x0F,):
                continue
            if "+i" in prim:
                continue
            # Real opcode rows name the instruction right after the encoding;
            # table rows of the manual (operands, exceptions, ...) do not.
            if not any(re.fullmatch(r"[A-Z][A-Z0-9]{1,}", t2) for t2 in toks[i:i + 6]):
                continue
            if i < len(toks) and toks[i].startswith("/i"):
                tail = ("none",)
            elif i < len(toks) and toks[i].startswith("/"):
                tail = ("d", int(toks[i][1])) if re.fullmatch(r"/[0-7]", toks[i]) else ("r",)
            elif i < len(toks) and toks[i].startswith("!("):
                tail = ("r",)
            elif extra and mapn in ("0F", "0F38", "0F3A") and pv in (0x00, 0x01, 0xAE, 0xC7, 0xBA):
                tail = ("lit", int(extra[0], 16))
            elif extra and mapn == "1" and pv in (0xC6, 0xC7):
                tail = ("lit", int(extra[0], 16))
            else:
                tail = ("none",)
            if plusr:
                tail = ("none",)
            mnem = next((t2 for t2 in toks[i:i + 6] if re.fullmatch(r"[A-Z][A-Z0-9]+-?", t2)), "")
            mnem = "" if mnem.rstrip("-") in OPEN_CODES else mnem.rstrip("-").lower()
            # Validity columns: 64-bit mode first, compatibility/legacy mode second.
            vals = [t2 for t2 in toks[i:] if t2 in VALIDITY_TOKENS][:2]
            compat = (len(vals) == 2 and vals[1] in ("Valid", "V")) or vals == ["V/V"]
            rows.append({"map": mapn, "mpfx": mpfx, "op": pv, "tail": tail, "plusr": plusr,
                         "line": lineno, "text": line.strip(), "mnem": mnem, "compat": compat})
    return rows


