SDM_ROWS = []


def sdm_key(form, strict=False):
    """Identifies one sdm_row_for() question, for the frozen answers."""
    return "|".join([form["map"], "%02X" % form["op"], form["mpfx"], canon(form["mnem"]),
                     repr(form["tail"]), str(bool(strict))])


def sdm_row_for(form, strict=False):
    """First SDM Vol.2 row with the same opcode, a compatible tail and the same mnemonic.

    strict=True requires the same tail (a bare SDM opcode does not list /r).
    Without the SDM reference files the answers recorded from SDM 093 are used
    (FROZEN_SDM_ANSWERS), so the generator runs from the repository alone.
    """
    if not SDM_ROWS:
        compat = FROZEN_SDM_ANSWERS.get(sdm_key(form, strict))
        return None if compat is None else {"compat": compat, "frozen": True}
    for row in SDM_ROWS:
        if row["map"] == form["map"] and row["op"] == form["op"] and row["mpfx"] == form["mpfx"] \
                and (not row["mnem"] or canon(row["mnem"]) == canon(form["mnem"])):
            if strict and row["tail"] != form["tail"]:
                continue
            if tail_compatible(row["tail"], form["tail"]):
                return row
    return None


def tail_compatible(st, ft):
    if st[0] == "none" or ft[0] == "none":
        return True
    if st[0] == ft[0]:
        return st == ft
    digit = lambda t: t[1] if t[0] == "d" else ((t[1] >> 3) & 7 if t[0] == "lit" else t[1])
    return st[0] in ("d", "i", "lit") and ft[0] in ("d", "i", "lit") and digit(st) == digit(ft)


def form_matches(sdm, form):
    if sdm["map"] != form["map"] or sdm["mpfx"] != form["mpfx"]:
        return False
    if form["plusr"]:
        if not (form["op"] <= sdm["op"] < form["op"] + 8):
            return False
    elif sdm["op"] != form["op"]:
        return False
    st, ft = sdm["tail"], form["tail"]
    # The SDM omits /digit and /r when the ModRM operand is the only one
    # (SETcc, PREFETCH-like rows), so a bare SDM opcode matches any tail.
    if st[0] == "none":
        return True
    if st[0] == "i" and ft[0] in ("i", "d", "lit"):
        return st[1] == (ft[1] if ft[0] == "i" else (ft[1] >> 3) & 7 if ft[0] == "lit" else ft[1])
    if ft[0] == "i" and st[0] in ("d", "lit"):
        return ft[1] == (st[1] if st[0] == "d" else (st[1] >> 3) & 7)
    if st[0] == "d" and ft[0] in ("d", "lit"):
        return st[1] == (ft[1] if ft[0] == "d" else (ft[1] >> 3) & 7)
    if st[0] == "lit" and ft[0] == "lit":
        return st[1] == ft[1]
    if st[0] == "r" and ft[0] == "r":
        return True
    if st[0] == "lit" and ft[0] in ("d", "i"):
        return False
    return False


