# Condition-code aliases printed in the Jcc/CMOVcc/SETcc rows of the map.
CC_ALIAS_NOISE = {"O", "NO", "B", "C", "NAE", "AE", "NB", "NC", "E", "Z", "NE", "NZ",
                  "BE", "NA", "A", "NBE", "S", "NS", "P", "PE", "NP", "PO", "L", "NGE",
                  "NL", "GE", "LE", "NG", "NLE", "G"}


def mnemonic_crosscheck(map_text_lines, known, insns_names):
    known_canon = set(_x87_norm(canon(k)) for k in known)
    """Mnemonic-level check of Tables A-2, A-3, A-6 and the x87 maps."""
    def in_range(lineno):
        if 330 <= lineno <= 742:
            return True
        if 1021 <= lineno <= 1181:
            return True
        if lineno >= 1225:
            return True
        return False
    seen = {}
    for lineno, line in enumerate(map_text_lines, 1):
        if not in_range(lineno):
            continue
        for tok in re.findall(r"\b[A-Z]{2,}H?\b", line):
            if tok in MAP_NOISE or tok in CC_ALIAS_NOISE:
                continue
            if re.fullmatch(r"[A-F]{1,2}H?", tok) or re.fullmatch(r"[0-9A-F]+H", tok):
                continue  # opcode bytes such as BA, DE, F7H
            seen.setdefault(tok, lineno)
    report = {"unknown": [], "dropped-only": [], "covered": 0}
    for tok, lineno in sorted(seen.items()):
        low = _x87_norm(canon(X87_ALIASES.get(tok.lower(), tok.lower())))
        if low in known_canon:
            report["covered"] += 1
        elif canon(low) in insns_names or low in insns_names:
            report["dropped-only"].append((tok, lineno))  # only forms dropped (64-bit, AMD, ...)
        else:
            report["unknown"].append((tok, lineno))
    return report


