# 6. Output
# ===========================================================================
def tag_sort_key(tag):
    if tag in ORDERED_TAGS:
        return (0, ORDERED_TAGS.index(tag), tag)
    return (1, 0, tag)


def fmt_line(form, indent):
    tag = "[%s]" % form["tag"]
    return "%s//  %-16s %-22s %s%s" % (
        " " * indent, tag, form["sdm"], form["mnem"].upper(),
        (" " + render_ops(form)) if form["ops"] else "")


def dedupe_entries(forms):
    """Keep the first form per (SDM line, mnemonic, table entry); later copies are noise."""
    seen = set()
    out = []
    for form in forms:
        key = (form["sdm"], form["mnem"], form["entry"], form["reason"] if not form["entry"] else None)
        if key in seen:
            continue
        seen.add(key)
        out.append(form)
    return out


def build_inline_block(forms, indent=4):
    lines = [" " * indent + BEGIN_MARK,
             " " * indent + "// Not implemented (generated). Each SDM line is followed by a ready-to-uncomment",
             " " * indent + "// table entry when the operands map to existing OperandType values, otherwise by the",
             " " * indent + "// reason it cannot be added yet.  Groups are per CPU feature."]
    current = None
    for form in forms:
        if form["tag"] != current:
            current = form["tag"]
            lines.append(" " * indent + "// ---- [%s] ----" % current)
        lines.append(fmt_line(form, indent))
        if form["entry"]:
            lines.append(" " * indent + "// " + form["entry"])
        else:
            lines.append(" " * indent + "//      " + form["reason"])
    lines.append(" " * indent + END_MARK)
    return lines


def build_inc(groups):
    out = []
    out.append("// opcodeTableFuture.inc")
    out.append("//")
    out.append("// Future-expansion opcode inventory. GENERATED by tests/ia32/tools/gen_future_opcodes.py;")
    out.append("// do not edit by hand. Comment-only: NOT part of any build (not listed in CMakeLists.txt,")
    out.append("// Makefile.am or Dismount.vcxproj) and not included anywhere.")
    out.append("//")
    out.append("// Covers every 32-bit/16-bit-valid opcode that dismount does not implement and that the")
    out.append("// current OpcodeEntry format cannot express:")
    out.append("//   * 0F 38 / 0F 3A three-byte legacy maps (SSSE3, SSE4.1/4.2, AES, SHA, ...)")
    out.append("//   * VEX-encoded forms (AVX, AVX2, FMA, F16C, BMI1/2, AVX-VNNI, GFNI, VAES, ...)")
    out.append("//   * EVEX-encoded forms (AVX-512 family, AVX10.2, ...)")
    out.append("//")
    out.append("// Why they are not table entries yet (see Include/dismount/proc/ia32/opcodeTable.h):")
    out.append("//   * OpcodeEntry holds one opcode byte (m_prefix) and no 3-byte escape (0F 38 / 0F 3A).")
    out.append("//     Needs: a 0F38/0F3A table pair and an escape check in IA32StreamDisassembler.")
    out.append("//   * No VEX/EVEX fields: map, pp (none/66/F2/F3), L (128/256/512), W, vvvv register,")
    out.append("//     and for EVEX the mask/zeroing/broadcast/rounding/SAE fields.")
    out.append("//     Needs: a VEX/EVEX prefix decoder that fills those fields.")
    out.append("//   * No vector operand types: OPND_SIMD_MODRM is xmm only. Needs OPND_YMM_MODRM,")
    out.append("//     OPND_ZMM_MODRM, OPND_KREG_MODRM, OPND_TMM_MODRM and a vvvv operand type.")
    out.append("//   * Mandatory prefixes (66/F2/F3) select a different instruction for the same byte.")
    out.append("//     Needs: a prefix-keyed lookup next to the opcode byte.")
    out.append("//")
    out.append("// 32-bit mode rule: C4 and C5 are VEX prefixes and 62 is an EVEX prefix ONLY when")
    out.append("// ModRM.mod == 11. For mod != 11 they are LES/LDS and BOUND. A decoder must therefore")
    out.append("// read the ModRM byte before it accepts any entry below. The same holds in 16-bit mode.")
    out.append("//")
    out.append("// Line format:  //  [feature]  <SDM encoding>  <MNEMONIC> <operands>")
    out.append("")
    for title, needs, forms in groups:
        out.append("// " + "=" * 74)
        out.append("// " + title)
        for n in needs:
            out.append("// needs: " + n)
        out.append("// " + "=" * 74)
        current = None
        for form in forms:
            if form["tag"] != current:
                current = form["tag"]
                out.append("// ---- [%s] ----" % current)
            out.append("//  [%s]  %-34s %s%s" % (form["tag"], form["sdm"], form["mnem"].upper(),
                                              (" " + render_ops(form)) if form["ops"] else ""))
        out.append("")
    return out


def replace_blocks(cpp_lines, table_blocks):
    """Drop old BEGIN..END blocks and insert new ones before each table's End marker."""
    cleaned = []
    skipping = False
    for line in cpp_lines:
        if line.strip().startswith(BEGIN_MARK):
            skipping = True
            continue
        if skipping:
            if line.strip().startswith(END_MARK):
                skipping = False
            continue
        cleaned.append(line)
    out = []
    current = None
    for line in cleaned:
        m = re.match(r"^const OpcodeEntry (gIa32\w+)\[\] = \{", line)
        if m:
            current = m.group(1)
        if current and line.strip() == "// End marker" and current in table_blocks:
            out.extend(table_blocks[current])
            current = None
        if line.startswith("};"):
            current = None
        out.append(line)
    return out


def main(argv):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--ref-dir", default=os.environ.get("DISMOUNT_SDM_REF", ""),
                    help="directory with sdm-vol2.txt and sdm-appendixA-opcode-map.txt "
                         "(optional, needed by --check)")
    ap.add_argument("--check", action="store_true", help="print the SDM cross-check report")
    ap.add_argument("--write", action="store_true", help="rewrite opcodeTable.cpp and the .inc")
    args = ap.parse_args(argv)
    sdm_vol2 = os.path.join(args.ref_dir, "sdm-vol2.txt") if args.ref_dir else ""
    sdm_map = os.path.join(args.ref_dir, "sdm-appendixA-opcode-map.txt") if args.ref_dir else ""
    sdm_present = bool(args.ref_dir) and os.path.isfile(sdm_vol2) and os.path.isfile(sdm_map)
    if args.check and not sdm_present:
        sys.stderr.write("--check needs the SDM reference files: sdm-vol2.txt and "
                         "sdm-appendixA-opcode-map.txt in %s\n"
                         "(pass --ref-dir DIR or set DISMOUNT_SDM_REF)\n"
                         % (args.ref_dir or "<no directory given>"))
        return 2

    with open(CPP_PATH, encoding="utf-8") as fh:
        cpp_text = fh.read()
    cpp_lines = cpp_text.split("\n")
    tables = parse_tables(cpp_lines)
    known = set()
    for name, entries in tables.items():
        for e in entries:
            if not e.invalid:
                n = e.name.lower()
                known.add(n)
                if "#" in n:   # string/size templates: pushf#d -> pushf, pushfd
                    known.update(n.replace("#", "").split("/") + [n.replace("#", "d").replace("dd", "d")])

    variants, stats = load_insns(INSNS_PATH)
    sdm_rows = []
    if sdm_present:
        sdm_rows = parse_vol2(sdm_vol2)
        SDM_ROWS.extend(sdm_rows)

    forms = []
    dropped = defaultdict(int)
    for v in variants:
        form = make_form(v)
        if form is None:
            dropped["no-opcode-bytes"] += 1
            continue
        reason = drop_reason(form)
        if reason:
            dropped[reason.split(" (")[0]] += 1
            form["drop"] = reason
            continue
        form["tag"] = feature_tag(form["mnem"], form["flags"])
        form["impl"] = implemented(form, tables)
        forms.append(form)

    # ND: drop a legacy alias when the same encoding is listed without ND.
    plain = set((f["map"], f["mpfx"], f["op"], f["plusr"], f["tail"]) for f in forms
                if "ND" not in f["flags"] and f["kind"] is None)
    # A key that has only ND forms keeps them (e.g. XLAT, whose only form is ND).
    kept = []
    for form in forms:
        if "ND" in form["flags"] and form["kind"] is None and \
                (form["map"], form["mpfx"], form["op"], form["plusr"], form["tail"]) in plain:
            dropped["ND alias of an existing encoding"] += 1
            continue
        if "ND" in form["flags"] and form["kind"] is not None:
            dropped["ND (APX NDD)"] += 1
            continue
        if "ND" in form["flags"] and sdm_row_for(form, strict=True) is None:
            dropped["ND alias, not listed in SDM 093"] += 1
            continue
        kept.append(form)
    forms = kept

    # Deduplicate: operand-size variants and repeated lines collapse to one.
    uniq = {}
    for form in forms:
        key = (form["map"], form["mpfx"], form["op"], form["plusr"], form["tail"],
               form["mnem"], form["sdm"], tuple(form["ops"]))
        if key not in uniq:
            uniq[key] = form
    forms = [f for f in uniq.values() if not f["impl"]]
    impl_count = len(uniq) - len(forms)
    for form in forms:
        form["entry"], form["reason"] = (None, None)
        if form["kind"] is None and form["map"] in ("1", "0F", "X87"):
            form["entry"], form["reason"] = make_entry_text(form)
        else:
            form["reason"] = "three-byte/VEX/EVEX form: see opcodeTableFuture.inc"

    # SDM cross-check: every legacy opcode in SDM Vol. 2 needs an insns.dat form.
    all_forms = []
    for v in variants:
        f = make_form(v)
        if f is not None:
            all_forms.append(f)
    missing_sdm = []
    for row in sdm_rows:
        probe = row
        if not any(form_matches(probe, f) for f in all_forms):
            if not any(form_matches(probe, {"map": s[0], "mpfx": s[1], "op": s[2], "plusr": False,
                                             "tail": s[3]}) for s in SUPPLEMENT):
                missing_sdm.append((row["line"], row["text"]))

    # Mnemonic cross-check against Appendix A tables
    xcheck = None
    if sdm_present:
        with open(sdm_map, encoding="utf-8", errors="replace") as fh:
            map_lines = fh.read().split("\n")
        insns_names = set(canon(v["mnem"]) for v in variants)
        cover_known = known | set(f["mnem"] for f in forms)
        xcheck = mnemonic_crosscheck(map_lines, cover_known, insns_names)

    if args.check or not args.write:
        print("insns.dat variants: %d   dropped: %s" % (len(variants), dict(stats)))
        print("implemented (already in tables, deduped): %d" % impl_count)
        print("missing legacy/x87 forms: %d" % sum(1 for f in forms if f["kind"] is None and f["map"] in ("1", "0F", "X87")))
        print("missing 0F38/0F3A/VEX/EVEX forms: %d" % sum(1 for f in forms if f["kind"] or f["map"] not in ("1", "0F", "X87")))
        print("dropped (filtered, reason -> count):")
        for k, v in sorted(dropped.items(), key=lambda kv: -kv[1]):
            print("   %5d  %s" % (v, k))
        if sdm_present:
            print("SDM Vol.2 legacy opcode lines: %d; with no insns.dat form: %d" % (len(sdm_rows), len(missing_sdm)))
            for lineno, text in missing_sdm:
                print("   MISSING-FROM-INSNS  vol2:%d  %s" % (lineno, text))
            print("Appendix A mnemonic cross-check: covered=%d dropped-only=%d unknown=%d" % (
                xcheck["covered"], len(xcheck["dropped-only"]), len(xcheck["unknown"])))
            for tok, lineno in xcheck["unknown"]:
                print("   UNKNOWN-MNEMONIC  %s (map line %d)" % (tok, lineno))
            for tok, lineno in xcheck["dropped-only"]:
                print("   DROPPED-ONLY      %s (map line %d)" % (tok, lineno))
        else:
            print("SDM cross-check skipped: no SDM reference files (see --ref-dir / DISMOUNT_SDM_REF)")
        if args.check and missing_sdm:
            return 1

    if not args.write:
        return 0

    inline = {"gIa32OneByteOpcodeTable": [], "gIa32TwoBytesOpcodeTable": [], "gIa32FPUOpcodeTable": []}
    selector = {"1": "gIa32OneByteOpcodeTable", "0F": "gIa32TwoBytesOpcodeTable", "X87": "gIa32FPUOpcodeTable"}
    for form in forms:
        if form["kind"] is None and form["map"] in selector:
            inline[selector[form["map"]]].append(form)
    table_blocks = {}
    for name, items in inline.items():
        items.sort(key=lambda f: (tag_sort_key(f["tag"]), f["op"], f["tail"], f["mnem"]))
        inline[name] = dedupe_entries(items)
        items = inline[name]
        table_blocks[name] = build_inline_block(items)
    new_cpp = replace_blocks(cpp_lines, table_blocks)
    if "\n".join(new_cpp) != cpp_text:
        with open(CPP_PATH, "w", encoding="utf-8", newline="") as fh:
            fh.write("\n".join(new_cpp))

    groups = []
    order = [("0F38", "Three-byte legacy map 0F 38 (SSSE3, SSE4.1/4.2, AES, SHA, MOVBE, ADX, ...)",
              ["Table entries need a 0F38 table and a 3-byte escape check",
               "Operand types: xmm (OPND_SIMD_MODRM ok), mm (none), ymm/zmm (none)"]),
             ("0F3A", "Three-byte legacy map 0F 3A (SSE4.1 blends/insert, PCLMULQDQ, AESKEYGEN, SHA, ...)",
              ["Table entries need a 0F3A table and a 3-byte escape check",
               "Immediate byte after ModRM is handled by OPND_IMMEDIATE_8BIT"]),
             ("VEX", "VEX-encoded (C4/C5 prefix; mod==11 only in 32-bit mode)",
              ["VEX prefix decoder: map, pp, L, W, vvvv register",
               "Operand types: OPND_YMM_MODRM, OPND_VVVV_REG, OPND_IMMEDIATE_8BIT"]),
             ("EVEX", "EVEX-encoded (62 prefix; mod==11 only in 32-bit mode): AVX-512 and AVX10",
              ["EVEX prefix decoder: map, pp, L'L, W, vvvv, V', aaa mask, z, b, R/R'",
               "Operand types: OPND_ZMM_MODRM, OPND_KREG_MODRM, broadcast/rounding/SAE",
               "Note: MAP5/MAP6 are the FP16 maps (AVX512-FP16)"])]
    for mapn, title, needs in order:
        if mapn in ("VEX", "EVEX", "XOP"):
            sel = [f for f in forms if f["kind"] == mapn]
        else:
            sel = [f for f in forms if f["kind"] is None and f["map"] == mapn]
        sel.sort(key=lambda f: (tag_sort_key(f["tag"]), f["op"], f["tail"], f["sdm"], f["mnem"]))
        groups.append((title, needs, sel))
    inc_lines = build_inc(groups)
    with open(INC_PATH, "w", encoding="utf-8", newline="") as fh:
        fh.write("\n".join(inc_lines) + "\n")
    print("wrote %s and %s" % (CPP_PATH, INC_PATH))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
